<script>
import { loadLanguage } from "../../i18n";

export default {
  data: () => ({
    practitioner: "",
    regStatus: "",
    regStatusCode: "",
    language: "en",
    searchMember: "",
    members: [],
    controlNumber: "",
    payments: {},
    previousYearPayment: {},
    dataLoading: {
      familyMembers: false,
      previousYearPayment: false,
      registrationStatus: false,
    },
  }),
  computed: {
    canRenew() {
      if (this.previousYearPayment.pending) {
        return false;
      }
      return true;
    },
    overlay() {
      if (
        this.dataLoading.familyMembers &&
        this.dataLoading.previousYearPayment &&
        this.dataLoading.registrationStatus
      ) {
        return false;
      }
      return true;
    },
    isMobile() {
      return screen.width <= 760;
    },
    membersHeaders() {
      let headers = [
        {
          text: this.$t("App.hardcoded-texts.Name"),
          value: "name",
        },
        {
          text: this.$t("App.hardcoded-texts.Registration Number"),
          value: "regNum",
        },
        {
          text: this.$t("App.hardcoded-texts.Fees Category"),
          value: "feecat",
        },
        {
          text: this.$t("App.hardcoded-texts.Required Fee"),
          value: "requiredfee",
        },
        {
          text: this.$t("App.hardcoded-texts.Paid Fee"),
          value: "paidfee",
        },
        {
          text: this.$t("App.hardcoded-texts.Pending Fee"),
          value: "pendingfee",
        },
        {
          text: this.$t("App.hardcoded-texts.Registration Status"),
          value: "reg_status",
        },
      ];
      if (this.regStatusCode) {
        headers.push({
          text: this.$t("App.hardcoded-texts.Action"),
          value: "action",
        });
      }
      return headers;
    },
  },
  methods: {
    handleMenuItemClick() {
      loadLanguage(this.language);
      localStorage.setItem("activeLocale", this.language);
    },
    getActiveFamilyMembers() {
      fetch("/site/student/getFamilyMembers/" + this.practitioner).then(
        (response) => {
          if (response.ok) {
            response.json().then((response) => {
              this.members = response;
              if (response.length) {
                let promises = [];
                for (let member of this.members) {
                  promises.push(
                    new Promise((resolve) => {
                      fetch("/site/student/latestRegistration/" + member.id)
                        .then((response) => {
                          resolve();
                          if (response.ok) {
                            this.$set(
                              member,
                              "reg_status",
                              this.$t("App.hardcoded-texts.Expired")
                            );
                            this.$set(member, "reg_status_color", "error");
                          } else {
                            response.json().then((response) => {
                              if (response.regStatus === "pending") {
                                this.$set(
                                  member,
                                  "reg_status",
                                  this.$t(
                                    "App.hardcoded-texts.Pending Approval"
                                  )
                                );
                                this.$set(
                                  member,
                                  "reg_status_code",
                                  response.regStatus
                                );
                                this.$set(
                                  member,
                                  "reg_status_color",
                                  "warning"
                                );
                              } else if (response.regStatus === "approved") {
                                this.$set(
                                  member,
                                  "reg_status",
                                  this.$t("App.hardcoded-texts.Active")
                                );
                                this.$set(
                                  member,
                                  "reg_status_color",
                                  "success"
                                );
                                this.$set(
                                  member,
                                  "reg_status_code",
                                  response.regStatus
                                );
                              } else if (response.regStatus === "rejected") {
                                this.$set(
                                  member,
                                  "reg_status",
                                  this.$t("App.hardcoded-texts.Rejected")
                                );
                                this.$set(member, "reg_status_color", "error");
                                this.$set(
                                  member,
                                  "reg_status_code",
                                  response.regStatus
                                );
                              }
                            });
                          }
                        })
                        .catch(() => {
                          resolve();
                        });
                    })
                  );
                }
                Promise.all(promises).then(() => {
                  this.dataLoading.familyMembers = true;
                });
              } else {
                this.dataLoading.familyMembers = true;
              }
            });
          } else {
            this.dataLoading.familyMembers = true;
            this.$store.commit("setMessage", {
              type: "error",
              text: "An error has occurred, try again later",
            });
          }
        }
      );
    },
  },
  created() {
    this.language = this.$i18n.locale;
    if (this.isMobile) {
      this.$store.state.minidrawer = true;
    }
    // if(this.$route.path !== "/") {
    //   this.$router.push(this.$route.path);
    // }
    if (this.$store.state.user.obj.resource) {
      let pract = this.$store.state.user.obj.resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference"
        );
      });
      if (pract && pract.valueReference && pract.valueReference.reference) {
        this.practitioner = pract.valueReference.reference.split("/")[1];
        fetch("/site/student/registrationStatus/" + this.practitioner).then(
          (response) => {
            response.json().then((response) => {
              this.dataLoading.registrationStatus = true;
              if (response.payments) {
                this.payments = response.payments;
              }
              if (
                response.controlNumber &&
                response.controlNumber.data.length
              ) {
                this.controlNumber =
                  response.controlNumber.data[0].controlnumber;
              }
              this.regStatus = response.status;
              this.regStatusCode = response.statusCode;
            });
          }
        );
        fetch(
          "/site/student/previousYearPaymentStatus/" + this.practitioner
        ).then((response) => {
          response.json().then((response) => {
            this.dataLoading.previousYearPayment = true;
            this.loading = false;
            this.previousYearPayment = response;
          });
        });
        this.getActiveFamilyMembers();
      } else {
        this.$router.go(-1);
      }
    } else {
      this.$router.push("/");
    }
  },
};
</script>

